chunks=[('Quaternion estimator update',source[source.index('static bool update_attitude'):source.index('static void process_one_sample')]),('Xbox mapping and readiness',source[source.index('static float stick_command'):source.index('static void telemetry_worker')])]
glossary=[('static','At file scope a function/name is local to this translation unit; inside report_targets, static variables retain their values across calls.'),('const','This named value cannot be assigned another value through that declaration.'),('float','A single-precision floating-point number; f suffix selects a float literal rather than double.'),('bool / true / false','Boolean type and values, used for readiness, checks and decisions.'),('uint8_t / uint16_t / uint32_t','Unsigned integers with8,16,32bits. raw sticks use16bits. Timing uses unsigned32bit subtraction, which tolerates a clock wrap for these short intervals.'),('void','No returned value, or an explicitly empty argument list in a C-style function declaration.'),('()','Group an expression, list function parameters, or call a function depending on position.'),('{}','Enclose a function or control block; in an initializer, collect initial values.'),('[]','Declare/index an array. [3] in a function parameter documents a three-component input; C++ passes a pointer and does not enforce its length.'),(';','Ends a declaration or statement. In a for header it separates initialization, condition and update.'),(',','Separates arguments, declarations or initializer elements. Each function argument has its own role.'),('= / ==','Assignment versus equality comparison. Exact zero is intentional here because the deadband function returns an explicit zero.'),('! / && / ||','Logical NOT, AND, OR. AND/OR short-circuit: the right side is evaluated only when needed.'),('< / > / <= / >=','Ordering comparisons; thresholds determine admission, not physical truth.'),('+ / - / * / /','Arithmetic. Unary - reverses a sign. In C++ * is multiplication here, unlike Python exponent **. Squaring is x*x.'),('? :','Conditional expression: condition ? value_when_true : value_when_false. This differs from the colon ending a Python if.'),('+= / /= / ++','Add-and-store, divide-and-store, increment. component++ advances one array index after the loop body.'),('(float) / (uint32_t)','Explicit type conversions. Float cast prevents integer-only arithmetic; unsigned timestamp subtraction supports rollover behavior.'),('. / ::','Object member access (xbox.isConnected) and C++ namespace/class qualification (the library Core type).'),('return','Finish this function, optionally returning a value. Returning false lets the caller stop invalid acquisition.'),('if / else / for','Conditional execution, alternative branch, bounded loop. Read the condition before the enclosed statements.'),('isfinite / fabsf / sqrtf','Check finite number; absolute float value; float square root. hypotf(a,b)=sqrt(a*a+b*b) evaluated with improved numerical handling.'),('sinf / cosf / atan2f / asinf','Trigonometric functions using radians. atan2f(y,x) includes quadrant; asinf input must be in[-1,1].'),('Serial.printf','Formatted diagnostic output. %u unsigned integer, %.3f float with3decimal digits, \\n newline. It does not command a motor.'),('0.08f / 32767.5f','8% normalized deadband and midpoint/half-span of0..65535. Normalization is s=(raw−32767.5)/32767.5.'),('0.6f / 0.4f','Weights of s and s³ after deadband rescaling: they sum to1, preserve endpoints and soften small deflections.'),('20.0f / 30.0f','Provisional display target limits:20degrees roll/pitch,30deg/s yaw. Not thrust percentages or validated flight limits.'),('100 / 300','100ms target report interval and300ms maximum report age. These are bench policy choices, not a demonstrated flight-link guarantee.')]
table='<table><tr><th>Character / word</th><th>Meaning in this code</th></tr>'+''.join('<tr><td><code>'+html.escape(a)+'</code></td><td>'+html.escape(b)+'</td></tr>' for a,b in glossary)+'</table>'
details='<h2>Study appendix · read the actual code</h2><p>Source shown below is the exact new application code, not pseudocode. Expand one function at a time. Reading order: inputs → validation → state update → outputs. Formatting is C-like with Allman braces. Library internals remain in the pinned Adafruit source.</p>'
for title,code in chunks:details+='<details><summary>'+title+'</summary><pre><code>'+html.escape(code)+'</code></pre></details>'
details+=table+'''<h2>Follow one update</h2><ol><li>Compute acceleration magnitude by squaring its3components, summing and taking the square root. Admit gravity correction only inside the documented magnitude tolerance.</li><li>Reject nonfinite acceleration/rate. At first usable sample, derive gravity tilt, then form q from half-angle sine/cosine products with initial yaw0.</li><li>Pass body gyro in deg/s (the library converts to rad/s), admitted acceleration or zero, and0.001s to updateIMU. A zero vector disables acceleration feedback in the library; gyro prediction continues.</li><li>Read all4quaternion components. Compute their norm, reject invalid/implausible values, divide every component by the norm and store the normalized state back.</li><li>Derive Euler diagnostic values from q; clamp pitch's sine input. The control state remains q; the preview still has no PID/actuator path.</li></ol><h2>Follow one Xbox command</h2><div class="eq">s=(raw−32767.5)/32767.5<br>d=0.08; &nbsp; |s|≤d ⇒ u=0<br>otherwise t=(|s|−d)/(1−d), &nbsp; u=sign(s)(0.6t+0.4t³)</div><p>raw is a16bit stick reading, s normalized signed travel, d deadband, t rescaled travel magnitude, u the gentler output. report_targets keeps targets at zero until a recent report and centered sticks have been observed. It then scales u to angle/rate limits. A stale report clears readiness and returns targets to zero. This is display-only behavior; idle notification cadence and physical signs must be validated before flight. The left vertical request remains dimensionless: no altitude estimator exists here.</p>'''
(out/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IntelQCopter quaternion fusion lesson</title><style>'+css+'</style><main>'+core+details+'</main></html>',encoding='utf-8')
td=teacher/'learning/quaternion-fusion';td.mkdir(parents=True,exist_ok=True)
